std::uint8_t FujiBusPacket::calcChecksum(const ByteBuffer& buf) const
{
    std::uint16_t chk = 0;

    for (std::size_t i = 0; i < buf.size(); ++i)
    {
        chk += buf[i];
        chk = (chk >> 8) + (chk & 0xFF); // fold carry
    }

    return static_cast<std::uint8_t>(chk);
}
